#!/usr/bin/env python3
"""Ground-up redesign: animated live BDH observatory tied to real training telemetry."""
import argparse,http.server,pathlib
HTML='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>HZ-0I · BDH Observatory</title><style>\n:root{--bg:#05070f;--panel:#0c1322;--line:#1e2b47;--ink:#dbe6ff;--dim:#7d8fb3}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(1200px 700px at 20% -10%,#10203f 0%,var(--bg) 55%);color:var(--ink);font:14px/1.5 ui-sans-serif,system-ui,sans-serif;min-height:100vh}\n.wrap{max-width:1500px;margin:0 auto;padding:18px 22px 60px}header{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;padding:6px 2px 16px;flex-wrap:wrap}\nh1{margin:0;font-size:26px;font-weight:800;background:linear-gradient(90deg,#38e1ff,#b57bff);-webkit-background-clip:text;background-clip:text;color:transparent}.sub{color:var(--dim);font-size:13px}\n.pill{display:inline-flex;align-items:center;gap:8px;padding:7px 14px;border:1px solid var(--line);border-radius:999px;background:#0a1224;color:var(--dim)}.dot{width:9px;height:9px;border-radius:50%;background:#3df5b3;box-shadow:0 0 10px #3df5b3;animation:pulse 1.6s infinite}@keyframes pulse{50%{opacity:.35}}\n#err{display:none;margin:0 0 12px;padding:10px 14px;border:1px solid #ff6b8b;border-radius:10px;background:#2a0f1a;color:#ffb3c4;font:12px ui-monospace,monospace}\n.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin:6px 0 16px}.stat{background:linear-gradient(160deg,var(--panel),#0a0f1c);border:1px solid var(--line);border-radius:14px;padding:12px 14px;position:relative;overflow:hidden}.stat::before{content:"";position:absolute;inset:0 0 auto 0;height:2px;background:linear-gradient(90deg,var(--c,#38e1ff),transparent)}.stat .k{color:var(--dim);font-size:11px;text-transform:uppercase;letter-spacing:.8px}.stat .v{font-size:23px;font-weight:800;font-variant-numeric:tabular-nums;margin-top:2px;color:var(--c,var(--ink))}.stat .s{color:var(--dim);font-size:11px}\n.card{background:linear-gradient(160deg,var(--panel),#0a0f1c);border:1px solid var(--line);border-radius:16px;padding:14px 16px;margin-bottom:14px}.card h2{margin:0 0 6px;font-size:14px;font-weight:700;color:#c9d7f5}.card .hint{color:var(--dim);font-size:11px;margin-bottom:6px}\ncanvas{width:100%;display:block;border-radius:10px}#arch{height:430px;background:radial-gradient(700px 300px at 50% 0%,#0e1830 0%,#080d1b 70%)}#loss,#state,#route,#layers{height:210px;background:#080d1c}\n.row2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.two{display:grid;grid-template-columns:1.4fr 1fr;gap:14px}\n@media(max-width:1000px){.row2,.two{grid-template-columns:1fr}.stats{grid-template-columns:repeat(3,1fr)}}\n</style></head><body><div class="wrap">\n<header><div><h1>HZ-0I · Persistent-State BDH Observatory</h1><div class="sub">Live training telemetry tied to the actual model — recurrent stream, conditional attention, fast weights, balanced MoE</div></div><div class="pill"><span class="dot"></span><span id="live">connecting…</span></div></header>\n<div id="err"></div>\n<div class="stats">\n<div class="stat" style="--c:#38e1ff"><div class="k">Throughput</div><div class="v" id="tput">—</div><div class="s">tokens / second</div></div>\n<div class="stat" style="--c:#ffc44d"><div class="k">Loss</div><div class="v" id="lossv">—</div><div class="s">train CE</div></div>\n<div class="stat" style="--c:#b57bff"><div class="k">Global step</div><div class="v" id="stepv">—</div><div class="s">updates</div></div>\n<div class="stat" style="--c:#4f7cff"><div class="k">Learning rate</div><div class="v" id="lrv">—</div><div class="s">schedule</div></div>\n<div class="stat" style="--c:#3df5b3"><div class="k">Trigger rate</div><div class="v" id="trgv">—</div><div class="s">conditional attn</div></div>\n<div class="stat" style="--c:#ff6b8b"><div class="k">Grad RMS</div><div class="v" id="grv">—</div><div class="s">gradient norm</div></div>\n</div>\n<div class="card"><h2>Actual BDH computation graph — live</h2><div class="hint">Each column is one capability layer (stride-2 of 8). Edge width/color follows measured hidden RMS and learned gates; dots flow at signal strength; expert node sizes follow real token assignments.</div><canvas id="arch" width="1500" height="430"></canvas></div>\n<div class="row2"><div class="card"><h2>Training dynamics (log10, auto)</h2><canvas id="loss" width="760" height="210"></canvas></div><div class="card"><h2>Weights / gradients (log10)</h2><canvas id="state" width="760" height="210"></canvas></div></div>\n<div class="two"><div class="card"><h2>Expert utilization / layer</h2><canvas id="route" width="900" height="210"></canvas></div><div class="card"><h2>Per-layer state RMS</h2><canvas id="layers" width="560" height="210"></canvas></div></div>\n</div><script>const $=id=>document.getElementById(id);\nwindow.onerror=(m,s,l)=>{const b=document.getElementById(\'err\');if(b){b.textContent=\'JS error: \'+m+\' @\'+l;b.style.display=\'block\'}};\nconst A=$(\'arch\'),ax=A.getContext(\'2d\');\nconst CV={loss:$(\'loss\'),state:$(\'state\'),route:$(\'route\'),layers:$(\'layers\')};\nconst CX={loss:CV.loss.getContext(\'2d\'),state:CV.state.getContext(\'2d\'),route:CV.route.getContext(\'2d\'),layers:CV.layers.getContext(\'2d\')};\nlet TRACE=[];\nfunction num(x){return isFinite(x)?x:null}\nfunction fmt(x,d=4){if(x==null)return\'—\';let a=Math.abs(x);if(a!==0&&(a>=1e4||a<1e-3))return x.toExponential(2);return x.toFixed(a>=100?1:d)}\nasync function load(){try{TRACE=await fetch(\'/trace?\'+Date.now()).then(r=>r.json());if(TRACE.length){const z=TRACE.at(-1);$(\'live\').textContent=\'step \'+z.step+\' · \'+z.layers.length+\' layers · live\';$(\'tput\').textContent=fmt(z.throughput_tok_s,1);$(\'lossv\').textContent=fmt(z.loss);$(\'stepv\').textContent=z.step;$(\'lrv\').textContent=fmt(z.lr,5);$(\'trgv\').textContent=fmt(z.trigger_rate,3);$(\'grv\').textContent=fmt(z.gradient_rms,3)}}catch(e){$(\'live\').textContent=\'waiting for trace…\'}}\n/* rounded rect without ctx.roundRect (portable) */\nfunction rr(ctx,x,y,w,h,r){r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}\n/* ---------- architecture ---------- */\nlet parts=null,partsN=-1;\nfunction buildParts(nL){parts=[];partsN=nL;const W=A.width,H=A.height,right=W-150,gap=Math.max(90,(right-120)/Math.max(1,nL-1||1)),cy=210,cx0=80;\n parts.push({id:\'in\',x:55,y:cy});\n for(let i=0;i<nL;i++){const x=cx0+i*gap;\n  parts.push({id:\'L\'+i,x,y:cy});\n  if(i<nL-1)parts.push({id:\'e\'+i,kind:\'edge\',from:\'L\'+i,to:\'L\'+(i+1)});\n  parts.push({id:\'a\'+i,kind:\'chip\',x,y:cy-96,lab:\'attn\'});\n  parts.push({id:\'f\'+i,kind:\'chip\',x,y:cy+128,lab:\'fast\'});}\n parts.push({id:\'out\',x:right+30,y:cy});\n if(nL>1)parts.push({id:\'eo\',kind:\'edge\',from:\'L\'+(nL-1),to:\'out\'});\n parts.forEach(p=>{if(p.kind===\'edge\'){p.t=Math.random();p.sp=.0016+Math.random()*.003}})}\nfunction pid(id){return parts.find(p=>p.id===id)}\nfunction pts(id){const p=pid(id);return p?{x:p.x,y:p.y}:null}\nfunction drawArch(){try{\n ax.clearRect(0,0,A.width,A.height);const z=TRACE.at(-1),ls=z?.layers||[],N=Math.max(2,ls.length);\n if(partsN!==N)buildParts(N);\n for(let i=0;i<N-1;i++){const a=pid(\'L\'+i),b=pid(\'L\'+(i+1)),q=ls[i]||{};const r=num(q.hidden_rms)||1,g=num(q.conditional_gate)||0;const w=Math.max(1.5,Math.min(9,(.6+r*1.2)*(1+Math.abs(g)*2)));const col=g>=0?\'#38e1ff\':\'#ff6b8b\';\n  ax.strokeStyle=col;ax.lineWidth=w;ax.globalAlpha=.55;ax.beginPath();ax.moveTo(a.x+55,a.y);ax.lineTo(b.x-55,b.y);ax.stroke();ax.globalAlpha=1}\n for(let i=0;i<N;i++){const p=pid(\'L\'+i),q=ls[i]||{},cg=num(q.conditional_gate)||0,mg=num(q.moe_gate)||0;\n  ax.strokeStyle=\'#ffc44d\';ax.lineWidth=.8+Math.abs(cg)*5;ax.beginPath();ax.moveTo(p.x,p.y-38);ax.lineTo(p.x,p.y-8);ax.stroke();\n  ax.strokeStyle=\'#b57bff\';ax.lineWidth=.8+Math.abs(mg)*5;ax.beginPath();ax.moveTo(p.x,p.y+38);ax.lineTo(p.x,p.y+8);ax.stroke()}\n for(let i=0;i<N;i++){const p=pid(\'L\'+i),q=ls[i]||{},r=num(q.hidden_rms)||1;\n  ax.shadowColor=\'#2b5fd9\';ax.shadowBlur=r*10;ax.fillStyle=\'#2b5fd9\';ax.beginPath();ax.arc(p.x,p.y,30,0,6.2832);ax.fill();ax.shadowBlur=0;\n  ax.fillStyle=\'#05070f\';ax.font=\'11px system-ui\';ax.textAlign=\'center\';ax.fillText(\'S\',p.x,p.y+4);\n  ax.fillStyle=\'#bfe0ff\';ax.font=\'10px system-ui\';ax.fillText(\'BDH \'+i,p.x,p.y-36);ax.fillStyle=\'#7d8fb3\';ax.fillText(\'rms \'+fmt(r,3),p.x,p.y+52);\n  const cg=num(q.conditional_gate)||0;chip(p,\'#ffc44d\',\'attn \'+(cg>=0?\'+\':\'\')+cg.toFixed(2),Math.abs(cg)*20,-96);\n  const fg=num(q.fast_gate)||0;chip(p,\'#3df5b3\',\'fast \'+(fg>=0?\'+\':\'\')+fg.toFixed(2),Math.abs(fg)*20,128);\n  const ec=q.expert_counts||[0,0,0,0];drawExperts(p.x,p.y+166,ec,Math.abs(num(q.moe_gate)||0))}\n ax.fillStyle=\'#8fb4ff\';ax.font=\'12px system-ui\';ax.textAlign=\'center\';ax.fillText(\'tokens\',60,210);ax.fillStyle=\'#b57bff\';ax.fillText(\'logits\',A.width-95,210);\n for(const p of parts){if(p.kind!==\'edge\')continue;p.t+=p.sp;if(p.t>1)p.t-=1;\n  const a=pts(p.from),b=pts(p.to);if(!a||!b)continue;const x=a.x+(b.x-a.x)*p.t,y=a.y+(b.y-a.y)*p.t;\n  ax.fillStyle=\'#ffffff\';ax.shadowColor=\'#ffffff\';ax.shadowBlur=6;ax.beginPath();ax.arc(x,y,2.4,0,6.2832);ax.fill();ax.shadowBlur=0}\n }catch(e){document.getElementById(\'err\').textContent=\'arch: \'+e.message;document.getElementById(\'err\').style.display=\'block\'}\n requestAnimationFrame(drawArch)}\nfunction chip(p,col,txt,glow,dy){ax.shadowColor=col;ax.shadowBlur=glow;ax.fillStyle=col;ax.globalAlpha=.9;rr(ax,p.x-36,p.y+dy-11,72,22,6);ax.fill();ax.globalAlpha=1;ax.shadowBlur=0;ax.fillStyle=\'#0a0f1c\';ax.font=\'10px system-ui\';ax.textAlign=\'center\';ax.fillText(txt,p.x,p.y+dy+3)}\nfunction drawExperts(x,y,ec,g){const tot=ec.reduce((a,b)=>a+b,0)||1,col4=[\'#b57bff\',\'#38e1ff\',\'#ffc44d\',\'#3df5b3\'];ec.forEach((n,i)=>{const ang=-Math.PI/2+i*Math.PI/2,px2=x+Math.cos(ang)*32,py2=y+Math.sin(ang)*32,r=4+Math.sqrt(n/Math.max(1,tot))*13;ax.fillStyle=col4[i];ax.globalAlpha=.55+Math.min(1,g*2);ax.beginPath();ax.arc(px2,py2,r,0,6.2832);ax.fill();ax.globalAlpha=1;ax.fillStyle=\'#7d8fb3\';ax.font=\'9px system-ui\';ax.textAlign=\'center\';ax.fillText(n,px2,py2+3)})}\n/* ---------- charts ---------- */\nfunction series(key){return TRACE.map(z=>{const v=z[key];return num(v)!=null?{x:z.step,y:num(v)}:null}).filter(Boolean)}\nfunction drawLog(ctx,key,col,label){const d=series(key);ctx.clearRect(0,0,ctx.canvas.width,ctx.canvas.height);if(d.length<2)return;const pad=44,top=16,bot=34,W=ctx.canvas.width,H=ctx.canvas.height;\n const lv=d.map(p=>Math.log10(Math.abs(p.y)+1e-12));let mn=Math.min(...lv),mx=Math.max(...lv);if(mx-mn<1e-6)mx+=1;const span=mx-mn;\n ctx.strokeStyle=\'#16233f\';ctx.fillStyle=\'#7d8fb3\';ctx.font=\'10px system-ui\';ctx.textAlign=\'left\';\n for(let g=0;g<=3;g++){const v=mn+span*g/3,y=top+(1-g/3)*(H-top-bot);ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(W-8,y);ctx.stroke();ctx.fillText(\'1e\'+(v).toFixed(1),4,y+3)}\n ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();lv.forEach((v,i)=>{const x=pad+(W-pad-8)*(i/(d.length-1)),y=top+(1-(v-mn)/span)*(H-top-bot);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();\n const last=d.at(-1),lx=pad+(W-pad-8),ly=top+(1-(lv.at(-1)-mn)/span)*(H-top-bot);ctx.fillStyle=col;ctx.beginPath();ctx.arc(lx,ly,3,0,6.2832);ctx.fill();\n ctx.fillStyle=col;ctx.font=\'bold 11px system-ui\';ctx.textAlign=\'right\';ctx.fillText(label+\' = \'+fmt(last.y,3),W-8,14)}\nfunction drawLog2(ctx,a,b,ca,cb,la,lb){const d1=series(a),d2=series(b);ctx.clearRect(0,0,ctx.canvas.width,ctx.canvas.height);const all=[...d1,...d2];if(all.length<2)return;const pad=44,top=16,bot=34,W=ctx.canvas.width,H=ctx.canvas.height;const lv1=d1.map(p=>Math.log10(Math.abs(p.y)+1e-12)),lv2=d2.map(p=>Math.log10(Math.abs(p.y)+1e-12));const lvs=[...lv1,...lv2];let mn=Math.min(...lvs),mx=Math.max(...lvs);if(mx-mn<1e-6)mx+=1;const span=mx-mn;\n ctx.strokeStyle=\'#16233f\';ctx.fillStyle=\'#7d8fb3\';ctx.font=\'10px system-ui\';ctx.textAlign=\'left\';for(let g=0;g<=3;g++){const v=mn+span*g/3,y=top+(1-g/3)*(H-top-bot);ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(W-8,y);ctx.stroke();ctx.fillText(\'1e\'+(v).toFixed(1),4,y+3)}\n function one(lv,d,col,label){ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();lv.forEach((v,i)=>{const x=pad+(W-pad-8)*(i/(Math.max(1,lv.length-1))),y=top+(1-(v-mn)/span)*(H-top-bot);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();const last=d.at(-1),lx=pad+(W-pad-8),ly=top+(1-(lv.at(-1)-mn)/span)*(H-top-bot);ctx.fillStyle=col;ctx.beginPath();ctx.arc(lx,ly,3,0,6.2832);ctx.fill();ctx.fillStyle=col;ctx.font=\'bold 11px system-ui\';ctx.textAlign=\'right\';ctx.fillText(label+\' = \'+fmt(last.y,3),W-8,14+ (label.includes(\'param\')?0:16))}\n one(lv1,d1,ca,la);one(lv2,d2,cb,lb)}\nfunction drawRoute(){const ctx=CX.route;ctx.clearRect(0,0,ctx.canvas.width,ctx.canvas.height);const z=TRACE.at(-1);if(!z)return;const ls=z.layers||[],N=ls.length,pad=40,top=14,bot=26,W=ctx.canvas.width,H=ctx.canvas.height,col4=[\'#b57bff\',\'#38e1ff\',\'#ffc44d\',\'#3df5b3\'];\n const maxE=Math.max(1,...ls.flatMap(q=>(q.expert_counts||[0,0,0,0])));const bw=Math.min(14,(W-pad-10)/(Math.max(1,N)*4));\n for(let i=0;i<N;i++){const ec=ls[i].expert_counts||[0,0,0,0];ec.forEach((n,e)=>{const x=pad+i*4*bw+e*bw+bw/2,h=n/maxE*(H-top-bot);ctx.fillStyle=col4[e];ctx.fillRect(x,H-bot-h,bw*.8,Math.max(2,h))})}\n ctx.fillStyle=\'#7d8fb3\';ctx.font=\'10px system-ui\';ctx.textAlign=\'left\';ctx.fillText(\'layers 0..\'+Math.max(0,N-1)+\' · height=token assignments · color=expert\',8,H-8)}\nfunction drawLayers(){const ctx=CX.layers;ctx.clearRect(0,0,ctx.canvas.width,ctx.canvas.height);const z=TRACE.at(-1);if(!z)return;const ls=z.layers||[],pad=40,top=14,bot=28,W=ctx.canvas.width,H=ctx.canvas.height;\n const v=ls.map(q=>Math.abs(num(q.hidden_rms)||0)+1e-9);const mx=Math.max(...v,1e-9);const bw=(W-pad-8)/Math.max(1,v.length);\n v.forEach((val,i)=>{const h=(Math.log10(val)/Math.log10(mx))*(H-top-bot)*.9,x=pad+i*bw;ctx.fillStyle=\'#38e1ff\';ctx.fillRect(x+2,H-bot-h,bw*.7,Math.max(2,h));ctx.fillStyle=\'#7d8fb3\';ctx.font=\'9px system-ui\';ctx.textAlign=\'center\';if(i%2===0)ctx.fillText(i,x+bw/2,H-14)});\n ctx.fillStyle=\'#7d8fb3\';ctx.font=\'10px system-ui\';ctx.textAlign=\'left\';ctx.fillText(\'layer index (log RMS)\',8,H-4)}\nsetInterval(load,1000);(function anim(){try{drawLog(CX.loss,\'loss\',\'#ffc44d\',\'LM loss\');drawLog2(CX.state,\'parameter_rms\',\'gradient_rms\',\'#38e1ff\',\'#ff6b8b\',\'param RMS\',\'grad RMS\');drawRoute();drawLayers()}catch(e){document.getElementById(\'err\').textContent=\'charts: \'+e.message;document.getElementById(\'err\').style.display=\'block\'}setTimeout(anim,700)})();\nload();requestAnimationFrame(drawArch);</script></body></html>'
class H(http.server.BaseHTTPRequestHandler):
 def do_GET(self):
  if self.path.startswith("/trace"):
   f=pathlib.Path(self.server.trace);b=f.read_bytes() if f.exists() else b"[]";self.send_response(200);self.send_header("Content-Type","application/json");self.send_header("Cache-Control","no-cache");self.end_headers();self.wfile.write(b)
  else:
   b=HTML.encode();self.send_response(200);self.send_header("Content-Type","text/html");self.send_header("Cache-Control","no-cache");self.end_headers();self.wfile.write(b)
 def log_message(self,*a):pass
if __name__=="__main__":
 a=argparse.ArgumentParser();a.add_argument("--trace",type=pathlib.Path,required=True);a.add_argument("--port",type=int,default=8765);o=a.parse_args();s=http.server.ThreadingHTTPServer(("127.0.0.1",o.port),H);s.trace=str(o.trace);print("http://127.0.0.1:%d"%o.port);s.serve_forever()
